(function () {
  'use strict';
  const E=window.ComplianceEngine, KEY='people-ledger-demo-v1';
  const $=s=>document.querySelector(s);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=c=>new Intl.NumberFormat('en-SG',{minimumFractionDigits:2,maximumFractionDigits:2}).format(c/100);
  const when=s=>{const d=new Date(s);return isNaN(d)?'—':new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(d);};
  const roles={hr:'HR 专员',finance:'财务复核人',director:'董事审批人',auditor:'只读查看人',system:'系统'};
  const names={overview:'工作总览',payroll:'员工与薪资',checks:'数据检查',reports:'报告与审批',evidence:'证据与记录'};
  const statuses={draft:['待财务复核','blue'],reviewed:['待董事审批','warning'],approved:['已批准','success'],rejected:['已退回','danger']};
  let state=E.createState(),actor='hr',selectedReport=null,toastTimer,stagedRows=null,storageWarning='';
  try{const saved=localStorage.getItem(KEY);if(saved)state=E.restore(JSON.parse(saved));}catch{storageWarning='本地记录无法读取，已恢复演示数据。';}
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{return false;}}
  function toast(message,error=false){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',4800);}
  function view(){const v=location.hash.slice(1);return names[v]?v:'overview';}
  function navigate(v){if(location.hash==='#'+v)render();else location.hash=v;}
  function button(label,action,extra='',kind=''){return `<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;}
  function badge(label,kind=''){return `<span class="badge ${kind}">${esc(label)}</span>`;}
  function can(role){return actor===role;}
  function reportCurrent(r){return !!r && r.revision===state.revision && r.check.ruleVersion===E.RULE_VERSION;}
  function doAction(action,payload={},destination){try{state=E.transition(state,actor,action,payload);const stored=save();render();if(destination)navigate(destination);toast(stored?'已保存操作记录':'操作已完成，但浏览器无法保存；关闭页面前请导出证据包',!stored);return true;}catch(error){toast(error.message,true);return false;}}
  function header(kicker,title,description,actions=''){return `<div class="page-header"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
  function runButton(){return button('运行数据检查','check',!['hr','finance'].includes(actor)?'disabled title="请切换为 HR 或财务角色"':'','primary');}
  function stat(label,value,detail,kind='',mark=''){return `<div class="stat ${kind}"><div class="stat-label">${label}<span class="stat-mark" aria-hidden="true">${mark}</span></div><div class="stat-number ${label.includes('金额')?'currency':''}">${value}</div><div class="stat-foot">${detail}</div></div>`;}
  function issueRows(issues){return issues.map(i=>`<tr><td><div class="issue-title">${esc(i.title)}</div><div class="issue-detail">${esc(i.detail)}</div><div class="issue-rule">${esc(i.rule)} · ${esc(i.ruleVersion)}</div></td><td><strong>${esc(i.name)}</strong><div class="issue-rule">${esc(i.recordId)}</div></td><td>${badge('待处理','warning')}</td><td>${button('修正记录','edit',`data-id="${esc(i.recordId)}" ${!can('hr')?'disabled title="切换到 HR 专员后修正"':''}`,'small')}</td></tr>`).join('');}
  function issueTable(issues){return `<div class="table-wrap"><table><thead><tr><th>检查事项</th><th>关联员工</th><th>状态</th><th>操作</th></tr></thead><tbody>${issueRows(issues)}</tbody></table></div>`;}
  function empty(icon,title,detail,action=''){return `<div class="empty"><div class="empty-icon" aria-hidden="true">${icon}</div><h2>${title}</h2><p>${detail}</p>${action}</div>`;}
  function overview(){
    const t=E.totals(state.records), fresh=E.currentCheck(state), issues=fresh?state.check.issues:[], latest=state.reports[0],approved=latest?.status==='approved'&&reportCurrent(latest);
    const departments={};state.records.forEach(r=>departments[r.department]=(departments[r.department]||0)+E.cents(r.basePay)+E.cents(r.allowances));
    const max=Math.max(...Object.values(departments),1);
    const steps=[['员工数据已载入',`${state.records.length} 条记录 · 数据版本 v${state.revision}`,true],['数据检查',fresh?`${issues.length} 个待处理问题`:'检查金额一致性与资料完整性',fresh],['财务复核',reportCurrent(latest)&&['reviewed','approved'].includes(latest.status)?'已完成财务复核':'由财务角色生成并复核报告',reportCurrent(latest)&&['reviewed','approved'].includes(latest.status)],['董事审批与证据导出',approved?'报告已获批准，可导出证据包':'审批通过后保留来源与决策记录',approved]];
    return header('WORKSPACE / OVERVIEW','让每一笔人员成本都有据可查','从员工数据到财务审批，查看本期工作进展。',button('查看员工数据','nav','data-view="payroll"')+runButton())+
      `<div class="stats">${stat('本期员工',state.records.length,'已载入虚构员工数据','','人')}${stat('应发金额 · SGD',money(t.gross),'基础工资 + 津贴','','S$')}${stat('待处理问题',fresh?issues.length:'—',fresh?`已检查 · ${when(state.check.at)}`:'尚未运行当前版本检查',fresh&&issues.length?'warning':'','!')}${stat('报告审批',approved?'已完成':reportCurrent(latest)?(latest.status==='reviewed'?'待审批':'待复核'):'未开始',latest?`${esc(latest.id)} · ${reportCurrent(latest)?'当前数据版本':'历史数据版本'}`:'完成检查后生成报告','','▧')}</div>`+
      `<div class="overview-guide"><strong>演示路线</strong><p>HR 检查并修正 3 个问题 → 财务生成与复核报告 → 切换董事批准 → 导出证据包。</p></div>`+
      `<div class="columns"><section class="card"><div class="card-head"><h2>人员成本分布</h2><span class="period-pill">应发金额 / SGD</span></div><div class="card-body">${Object.entries(departments).map(([d,n])=>`<div class="chart-row"><span>${esc(d)}</span><div class="chart-bar" role="img" aria-label="${esc(d)} ${money(n)} SGD"><span style="width:${Math.max(3,n/max*100)}%"></span></div><span class="chart-number">${money(n)}</span></div>`).join('')}<div class="chart-summary"><span>扣款合计 ${money(t.deductions)}</span><strong>应付净额 ${money(t.expected)}</strong></div></div></section><section class="card"><div class="card-head"><h2>本期工作流</h2>${badge('版本 v'+state.revision,'blue')}</div><div class="card-body">${steps.map(([title,detail,done],i)=>`<div class="progress-flow"><span class="step-num ${done?'complete':''}">${done?'✓':i+1}</span><div><h3>${title}</h3><p>${detail}</p></div></div>`).join('')}</div></section></div>`+
      `<section class="card"><div class="card-head"><div><h2>优先处理</h2><p>每一项问题都关联到具体员工与检查规则。</p></div><button class="text-btn" data-action="nav" data-view="checks">查看全部</button></div>${!fresh?empty('✓','先检查，再作判断','运行当前版本的数据检查，找出需要处理的记录。',runButton()):issues.length?issueTable(issues.slice(0,3)):empty('✓','当前演示规则未发现异常','可以切换为财务复核人，生成本期报告草稿。',button('前往报告','nav','data-view="reports"'))}</section>`;
  }
  function payroll(){
    const fresh=E.currentCheck(state),ids=new Set(fresh?state.check.issues.map(i=>i.recordId):[]);
    return header('PEOPLE / PAYROLL','员工与薪资','金额单位 SGD。所有示例人员与业务记录均为虚构。',button('下载 CSV 模板','template')+button('导入 CSV','import',!can('hr')?'disabled title="仅 HR 演示角色可导入"':'','primary'))+
      `<div class="intro-line"><span>数据版本 <strong>v${state.revision}</strong> · ${state.records.length} 名员工。修改或替换数据后，需要重新检查并生成报告。</span>${badge('当前浏览器保存','blue')}</div>`+
      `<section class="card"><div class="card-head"><h2>员工薪资明细</h2>${badge(can('hr')?'HR 可编辑':'当前角色只读')}</div><div class="table-wrap"><table><thead><tr><th>员工</th><th>部门 / 成本中心</th><th>期间</th><th>基础工资</th><th>津贴</th><th>扣款</th><th>应付净额</th><th>录入实付</th><th>凭证引用</th><th>检查状态</th><th>操作</th></tr></thead><tbody>${state.records.map(r=>`<tr><td><div class="cell-person"><span class="person-icon" aria-hidden="true">${esc(r.name.slice(0,1))}</span><div><strong>${esc(r.name)}</strong><small>${esc(r.id)}</small></div></div></td><td>${esc(r.department)}<div class="issue-rule ${!r.costCenter?'missing':''}">${esc(r.costCenter||'待补充')}</div></td><td>${esc(r.period)}</td><td class="money">${money(E.cents(r.basePay))}</td><td class="money">${money(E.cents(r.allowances))}</td><td class="money">${money(E.cents(r.deductions))}</td><td class="money">${money(E.cents(r.basePay)+E.cents(r.allowances)-E.cents(r.deductions))}</td><td class="money">${money(E.cents(r.netPaid))}</td><td class="${!r.evidence?'missing':''}">${esc(r.evidence||'待补充')}</td><td>${!fresh?badge('待检查'):ids.has(r.id)?badge('有待办','warning'):badge('无异常','success')}</td><td>${button('编辑','edit',`data-id="${esc(r.id)}" ${!can('hr')?'disabled':''}`,'small')}</td></tr>`).join('')}</tbody></table></div><div class="table-note">应付净额 = 基础工资 + 津贴 − 录入扣款。此处未计算 CPF、税款或其他法定金额；凭证编号仅为引用。</div></section>`+
      `<p class="footnote">导入使用“替换全部记录”的方式，提交前会显示预览。报告及操作历史仍保留；请仅使用模拟数据。</p>`;
  }
  function checks(){const fresh=E.currentCheck(state),check=state.check;
    return header('CONTROL / REVIEW','数据检查','用确定性规则核对金额与资料完整性，每次检查保留数据版本。',runButton())+
      (check&&!fresh?`<div class="intro-line amber">员工数据已更新。下面是 v${check.revision} 的历史检查结果，请重新运行检查。</div>`:'')+
      `<section class="card"><div class="card-head"><div><h2>${fresh?(check.issues.length?`${check.issues.length} 个事项待处理`:'当前规则未发现异常'):'检查结果'}</h2><p>${check?`检查时间 ${when(check.at)} · 规则 ${esc(check.ruleVersion)} · 数据版本 v${check.revision}`:'先运行检查，再根据结果修正资料。'}</p></div>${fresh?badge(check.issues.length?'需要处理':'检查完成',check.issues.length?'warning':'success'):badge('待检查')}</div>${!check?empty('✓','检查尚未开始','将核对净薪资、凭证引用、成本中心和扣款范围。',runButton()):check.issues.length?issueTable(check.issues):empty('✓','本次检查已完成','此结果只覆盖下面列出的演示规则。生成报告后仍需人工复核。',button('前往报告与审批','nav','data-view="reports"'))}</section>`+
      `<section class="card"><div class="card-head"><h2>当前启用的演示规则</h2><span class="period-pill">${E.RULE_VERSION}</span></div><div class="card-body rules">${[['PAY-001','净薪资金额一致','比较基础工资 + 津贴 − 扣款，与录入实付金额。'],['DOC-001','凭证引用完整','检查工资单或付款凭证编号是否填写；不验证文件真伪。'],['ORG-001','成本中心完整','检查每名员工是否关联成本中心。'],['PAY-002','扣款范围检查','提示扣款高于基础工资与津贴合计的记录。']].map(([id,title,detail])=>`<div class="rule"><code>${id}</code><h3>${title}</h3><p>${detail}</p></div>`).join('')}</div></section>`;
  }
  function paper(r){const t=r.check.totals,st=statuses[r.status]||statuses.draft;
    return `<article class="paper"><div class="paper-kicker">PEOPLELEDGER / REVIEW DOCUMENT</div><h2>人力与财务合规复核草稿</h2><div class="paper-meta"><span>${esc(r.id)} · v${r.revision}</span><span>${when(r.createdAt)}</span><span>本地模板生成 · 未调用 AI</span>${badge(st[0],st[1])}${!reportCurrent(r)?badge('数据已更新','warning'):''}</div><p>本次汇总覆盖 <strong>${r.records.length} 名员工</strong>，期间为 ${esc([...new Set(r.records.map(x=>x.period))].join('、'))}。金额使用确定性计算，结论须由财务人员复核。</p><div class="paper-summary"><div><small>应发总额 / SGD</small><strong>${money(t.gross)}</strong></div><div><small>应付净额 / SGD</small><strong>${money(t.expected)}</strong></div><div><small>录入实付 / SGD</small><strong>${money(t.paid)}</strong></div></div><h3>检查结论与待决事项</h3><p>基于规则 ${esc(r.check.ruleVersion)}，发现 <strong>${r.check.issues.length} 个待处理问题</strong>。${r.check.issues.length?'请先修正数据，再重新检查和生成报告。':'在已配置规则范围内未发现异常，可进入人工复核。'}</p>${r.check.issues.map(i=>`<div class="decision"><p><strong>${esc(i.recordId)} · ${esc(i.title)}</strong></p><p>${esc(i.detail)}</p><small>${esc(i.rule)}</small></div>`).join('')}<h3>数据来源快照</h3><div class="table-wrap"><table><thead><tr><th>员工编号 / 姓名</th><th>应付净额</th><th>录入实付</th><th>凭证引用</th></tr></thead><tbody>${r.records.map(x=>`<tr><td>${esc(x.id)} / ${esc(x.name)}</td><td>${money(E.cents(x.basePay)+E.cents(x.allowances)-E.cents(x.deductions))}</td><td>${money(E.cents(x.netPaid))}</td><td>${esc(x.evidence||'未提供')}</td></tr>`).join('')}</tbody></table></div><h3>人工复核与审批</h3>${r.decisions.length?r.decisions.map(d=>`<div class="decision"><p><strong>${esc(roles[d.actor])} · ${esc({review:'复核通过',approve:'批准',reject:'退回'}[d.action])}</strong></p><p>${esc(d.note)}</p><small>${when(d.at)} · 演示角色操作</small></div>`).join(''):'<p class="muted">尚无人工复核或审批记录。</p>'}<p class="scope">范围说明：本报告由本地模板生成，未接入 AI 模型。凭证引用不代表原始文件已上传或验证。演示不计算 CPF 或税款，不进行法定合规判断。角色切换不是身份认证，浏览器记录不具备防篡改保证。本草稿不构成审计意见或合规保证。</p></article>`;
  }
  function reports(){
    const fresh=E.currentCheck(state);
    let out=header('REPORTS / APPROVAL','报告与审批','保留数据快照与审批意见，让每一次判断可追溯。',button('生成报告草稿','draft',!can('finance')||!fresh?'disabled title="财务角色完成当前数据检查后可生成"':'','primary'));
    if(!can('finance')&&!state.reports.length)out+='<div class="intro-line">请在右上角切换为“财务复核人”，完成检查后生成报告。</div>';
    if(!state.reports.length)return out+`<section class="card">${empty('▧','还没有报告草稿','完成数据检查后，财务角色可生成报告。待处理问题会随快照一起保留，未解决前不能提交复核。',button('前往数据检查','nav','data-view="checks"'))}</section>`;
    const r=state.reports.find(x=>x.id===selectedReport)||state.reports[0];selectedReport=r.id;const current=reportCurrent(r);
    out+=`<div class="report-layout"><div class="report-list">${state.reports.map(x=>{const st=statuses[x.status]||statuses.draft;return `<button class="report-item ${x.id===r.id?'active':''}" data-action="select-report" data-id="${esc(x.id)}"><strong>${esc(x.id)}</strong><small>${when(x.createdAt)} · 数据 v${x.revision}</small>${badge(st[0],st[1])}${!reportCurrent(x)?'<small style="margin:8px 0 0">历史数据版本</small>':''}</button>`;}).join('')}</div><div><div class="report-actionbar">${r.status==='draft'?button('财务复核并提交','review',`data-id="${esc(r.id)}" ${!can('finance')||!current||r.check.issues.length?'disabled':''}`,'primary'):''}${r.status==='reviewed'?button('批准报告','approve',`data-id="${esc(r.id)}" ${!can('director')||!current?'disabled':''}`,'primary')+button('退回修改','reject',`data-id="${esc(r.id)}" ${!can('director')||!current?'disabled':''}`,'danger'):''}${button('打印 / 保存 PDF','print',`data-id="${esc(r.id)}"`)}<span class="muted">${!current?'历史版本：请重新检查并生成报告':r.check.issues.length?'待处理问题解决后可提交复核':r.status==='rejected'?'请由财务生成新草稿，重新复核':r.status==='approved'?'已完成演示审批流程':'使用对应演示角色完成审批'}</span></div>${paper(r)}</div></div>`;
    return out;
  }
  function eventDetail(v){if(typeof v==='string')return v;if(v?.recordId)return `${v.recordId}：${v.note}；${v.changes.map(x=>`${x.field}：${x.before||'空'} → ${x.after||'空'}`).join('；')}`;return `${v?.reportId||''}：${v?.note||''}`;}
  function evidence(){return header('EVIDENCE / HISTORY','证据与记录','导出员工数据、检查结果、报告快照和人工决策，供演示复查。',button('重置演示数据','reset'))+
    `<div class="export-grid"><section class="export-card"><h2>完整演示证据包</h2><p>JSON 文件包含当前数据、历史报告、规则结果和全部操作记录，并标明报告审批状态。</p>${button('下载证据包 JSON','export-json','','primary')}</section><section class="export-card"><h2>当前员工薪资明细</h2><p>CSV 文件保留当前版本的全部薪资字段与凭证编号，可用于表格复核。</p>${button('下载薪资 CSV','export-csv')}</section></div>`+
    `<div class="intro-line amber">本页为浏览器本地操作历史，可被本机使用者修改或清除，不等同于企业级审计日志。凭证编号仅为引用。</div>`+
    `<section class="card"><div class="card-head"><h2>操作记录</h2><span class="period-pill">${state.events.length} 条记录</span></div><div class="card-body timeline">${state.events.slice().reverse().map(ev=>`<div class="timeline-item"><time datetime="${esc(ev.at)}">${when(ev.at)}<br><small>${esc(ev.id)}</small></time><div><p><strong>${esc(ev.action)}</strong>　${badge(roles[ev.actor]||ev.actor)}</p><small>${esc(eventDetail(ev.detail))}</small><small>数据版本 v${ev.revision}</small></div></div>`).join('')}</div></section>`;}
  function render(){const v=view();$('#main').innerHTML=({overview,payroll,checks,reports,evidence})[v]();$('#crumb').textContent=names[v];document.title=`${names[v]} · PeopleLedger`;document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.view===v;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#nav-count').textContent=E.currentCheck(state)&&state.check.issues.length?state.check.issues.length:'';$('#avatar').textContent={hr:'HR',finance:'FN',director:'BD',auditor:'RO'}[actor];}
  function modal(title,body,actions){$('#modal').innerHTML=`<div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="close" type="button" data-close aria-label="关闭">×</button></div>${body}<div class="modal-actions">${button('取消','close')}${actions}</div>`;$('#modal').showModal();}
  function close(){stagedRows=null;$('#modal').close();}
  function field(label,key,value,extra=''){return `<label class="field">${label}<input name="${key}" value="${esc(value)}" required ${extra}></label>`;}
  function edit(id){if(!can('hr'))return toast('请切换为 HR 专员',true);const r=state.records.find(x=>x.id===id);if(!r)return;
    modal(`编辑员工记录 · ${esc(r.id)}`,`<form id="edit-form" class="modal-body"><p>修改将形成新的数据版本。请注明依据，已有报告保留为历史快照。</p><div class="form-grid">${field('姓名','name',r.name,'maxlength="80"')}${field('部门','department',r.department,'maxlength="80"')}${field('成本中心','costCenter',r.costCenter,'maxlength="80"')}${field('薪资期间','period',r.period,'type="month"')}${field('基础工资 · SGD','basePay',r.basePay,'inputmode="decimal"')}${field('津贴 · SGD','allowances',r.allowances,'inputmode="decimal"')}${field('扣款 · SGD','deductions',r.deductions,'inputmode="decimal"')}${field('录入实付 · SGD','netPaid',r.netPaid,'inputmode="decimal"')}${field('凭证引用编号','evidence',r.evidence,'maxlength="240"')}<label class="field full">修改说明<textarea name="note" required maxlength="500" placeholder="例如：依据演示工资单，修正实付净额。"></textarea></label></div><div id="form-error" class="form-error" role="alert"></div></form>`,button('保存修改','save-edit',`data-id="${esc(id)}"`,'primary'));
    // Missing optional values are allowed, so users can edit one finding at a time.
    $('#edit-form [name="costCenter"]').required=false;$('#edit-form [name="evidence"]').required=false;
    $('#edit-form').addEventListener('submit',ev=>{ev.preventDefault();saveEdit(id);});
  }
  function saveEdit(id){const form=$('#edit-form');if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));const note=values.note;delete values.note;try{const next=E.transition(state,actor,'edit',{id,changes:values,note});state=next;const stored=save();close();render();toast(stored?'已保存。请重新运行数据检查。':'已修改，但无法保存到浏览器；请导出证据包',!stored);}catch(error){$('#form-error').textContent=error.message;}}
  function decide(action,id){const title={review:'财务复核并提交',approve:'董事批准报告',reject:'退回报告'}[action];modal(title,`<form id="decision-form" class="modal-body"><p>${esc(id)} · 请写明复核结论或退回原因。此处为角色流程演示。</p><label class="field">${action==='reject'?'退回原因':'审批意见'}<textarea name="note" maxlength="1000" required placeholder="请填写具体意见"></textarea></label><div class="form-error" id="form-error" role="alert"></div></form>`,button('确认'+(action==='reject'?'退回':action==='review'?'复核':'批准'),'save-decision',`data-id="${esc(id)}" data-kind="${action}"`,'primary'));$('#decision-form').addEventListener('submit',ev=>{ev.preventDefault();saveDecision(action,id);});}
  function saveDecision(action,id){const f=$('#decision-form');if(!f.reportValidity())return;try{state=E.transition(state,actor,action,{id,note:new FormData(f).get('note')});const stored=save();close();render();toast(stored?'审批意见已记录':'意见已记录，但无法保存到浏览器；请导出证据包',!stored);}catch(error){$('#form-error').textContent=error.message;}}
  function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
  async function stageImport(file){if(!file)return;try{if(!can('hr'))throw new Error('请切换为 HR 专员');if(file.size>1024*1024)throw new Error('文件不能超过 1 MB');const rows=E.parseCSV(await file.text());stagedRows=rows;const t=E.totals(rows);modal('确认替换员工数据',`<div class="modal-body"><p>将以 <strong>${rows.length} 条记录</strong>替换当前 ${state.records.length} 条记录。应发合计 SGD ${money(t.gross)}。现有报告和操作历史会保留。</p><div class="table-wrap"><table><thead><tr><th>员工编号</th><th>姓名</th><th>录入实付</th></tr></thead><tbody>${rows.slice(0,5).map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.name)}</td><td>${money(E.cents(r.netPaid))}</td></tr>`).join('')}</tbody></table></div><p style="margin-top:16px">预览前 ${Math.min(rows.length,5)} 行。请仅导入模拟数据。</p></div>`,button('确认替换','confirm-import','','primary'));}catch(error){toast(error.message,true);}finally{$('#import-file').value='';}}
  document.addEventListener('click',event=>{const b=event.target.closest('button[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;
    if(action==='nav')navigate(b.dataset.view);
    else if(action==='check')doAction('check',{},'checks');
    else if(action==='edit')edit(id);
    else if(action==='save-edit')saveEdit(id);
    else if(action==='close')close();
    else if(action==='draft'){if(doAction('draft',{},'reports')){selectedReport=state.reports[0].id;render();}}
    else if(['review','approve','reject'].includes(action))decide(action,id);
    else if(action==='save-decision')saveDecision(b.dataset.kind,id);
    else if(action==='select-report'){selectedReport=id;render();}
    else if(action==='template')download('people-ledger-template.csv',E.toCSV(E.normalizeRows(E.SAMPLE)),'text/csv;charset=utf-8');
    else if(action==='import')$('#import-file').click();
    else if(action==='confirm-import'){const rows=stagedRows;if(rows&&doAction('import',{rows},'payroll'))close();}
    else if(action==='export-json')download(`people-ledger-evidence-v${state.revision}.json`,JSON.stringify(E.evidencePackage(state),null,2),'application/json;charset=utf-8');
    else if(action==='export-csv')download(`people-ledger-payroll-v${state.revision}.csv`,E.toCSV(state.records),'text/csv;charset=utf-8');
    else if(action==='print'){const r=state.reports.find(x=>x.id===id);if(r){$('#print-area').innerHTML=paper(r);window.print();}}
    else if(action==='reset')resetDialog();
    else if(action==='confirm-reset'){state=E.createState();selectedReport=null;const stored=save();close();navigate('overview');render();toast(stored?'演示数据已重置':'已重置，但浏览器无法保存',!stored);}
  });
  $('#modal').addEventListener('click',ev=>{if(ev.target.closest('[data-close]'))close();});
  $('#modal').addEventListener('cancel',()=>{stagedRows=null;});
  $('#role').addEventListener('change',ev=>{actor=ev.target.value;render();toast(`已切换为${roles[actor]}（演示）`);});
  function resetDialog(){modal('重置演示数据','<div class="modal-body"><p>将恢复 6 条初始记录，并清除当前浏览器的全部报告与操作历史。需要保留时，请先下载证据包。</p></div>',button('确认重置','confirm-reset','','danger'));}
  $('#reset').addEventListener('click',resetDialog);
  $('#import-file').addEventListener('change',ev=>stageImport(ev.target.files[0]));
  window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});
  // Read-only WebMCP summary, when the browser supports the proposed interface.
  if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'read_compliance_demo_summary',title:'读取演示工作流摘要',description:'Read the browser-local demo totals, findings and report status without changing any data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object');return {mode:'browser-local-demo',revision:state.revision,employeeCount:state.records.length,totalsInCents:E.totals(state.records),checkCurrent:!!E.currentCheck(state),findingCount:E.currentCheck(state)?state.check.issues.length:null,latestReport:state.reports[0]?{id:state.reports[0].id,status:state.reports[0].status,revision:state.reports[0].revision}:null};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
  render();if(storageWarning)toast(storageWarning,true);
})();
